const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date = value => { if(!value) return '—'; const d=new Date(value+'T00:00:00'); return Number.isNaN(+d)?esc(value):d.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}); };
const pretty = v => String(v??'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const safeUrl = v => {try{const u=new URL(v,location.origin);return ['http:','https:'].includes(u.protocol)?u.href:'#'}catch{return '#'}};
function flagFor(code){if(!/^[A-Za-z]{2}$/.test(code||''))return '🌐';return String.fromCodePoint(...code.toUpperCase().split('').map(c=>127397+c.charCodeAt(0)))}
const state={boot:null,dataset:null,view:'overview',scenario:null,requirements:[],selectedRule:null,reqCountry:'',reqDate:'',query:'',preview:null,datasetPreview:null,comparison:null,compareBefore:'',compareAfter:'',chat:[],importType:'rules',assistantScenario:''};
const content=$('#app-content');
async function api(path,opts={}){const res=await fetch(path,{headers:{'Content-Type':'application/json',...(opts.headers||{})},...opts});let data;try{data=await res.json()}catch{data={error:'The service returned an unreadable response.'}}if(!res.ok)throw new Error(data.error||`Request failed (${res.status})`);return data}
function notify(message,type=''){const n=$('#notice');n.textContent=message;n.className=`notice ${type}`;n.hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>n.hidden=true,6000)}
function badge(value){let val=String(value||'unknown').toLowerCase();return `<span class="badge ${esc(val)}">${esc(pretty(val))}</span>`}
function scenarioName(s){return s?.name||s?.id||'Scenario'}
function scenarios(){return state.boot?.scenarios||[]}
function planById(id){if(state.boot?.approved_scenario?.id===id)return state.boot.approved_scenario;return scenarios().find(s=>s.id===id)||null}
async function load(){content.innerHTML='<div class="loading"><span class="spinner"></span>Loading supply picture…</div>';try{const previousTrial=state.boot?.trial?.id;const [boot,dataset]=await Promise.all([api('/api/bootstrap'),api('/api/dataset')]);state.boot=boot;state.dataset=dataset;if(previousTrial&&previousTrial!==state.boot.trial?.id){state.comparison=null;state.compareBefore='';state.compareAfter='';state.assistantScenario='';state.chat=[]}state.scenario=state.boot.approved_scenario;const codes=countryList().map(c=>c.iso_code||c.id);if(!codes.includes(state.reqCountry))state.reqCountry=codes[0]||'';state.reqDate=state.boot.dataset_summary?.as_of||state.boot.approved_scenario?.as_of||state.reqDate;$('#provider-label').textContent=`${state.boot.provider?.active||state.boot.provider||'Local'} feature provider`;$('#scenario-count').textContent=scenarios().length;render()}catch(e){content.innerHTML=`<div class="card empty"><b>Supply workspace unavailable</b>${esc(e.message)}<p>Check that the local API is running, then refresh.</p><button class="button" id="retry">Retry connection</button></div>`;$('#retry')?.addEventListener('click',load)}}
function nav(view){state.view=view;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const labels={overview:'Control tower',requirements:'Requirements',scenarios:'Scenarios',assistant:'Planner assistant',imports:'Data & research',audit:'Audit history'};$('#top-context').textContent=labels[view]||'Control tower';render()}
function render(){if(!state.boot)return;const map={overview:renderOverview,requirements:renderRequirements,scenarios:renderScenarios,assistant:renderAssistant,imports:renderImports,audit:renderAudit};(map[state.view]||renderOverview)()}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${esc(state.boot.trial?.name||'Trial supply program')}</div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`}
function countryList(){return state.boot.jurisdictions||[]}
function shipmentRows(plan){return plan?.shipments||[]}
function renderOverview(){const pending=(state.boot.scenarios||[]).find(s=>s.status==='proposed');const p=state.boot.approved_scenario||pending||{};const hasPlan=Boolean(p.id);const m=p.metrics||{};const ships=shipmentRows(p),jur=countryList(),alerts=state.boot.alerts||[];const byCountry=new Map(ships.map(s=>[s.country_code,s]));const tiles=jur.map(c=>{const code=c.iso_code||c.id;const sh=byCountry.get(code);const risk=sh?.risk_band||'unknown';return `<button class="country-tile ${esc(risk)}" data-country="${esc(code)}" title="Open ${esc(c.name)} requirements"><span class="tile-state"></span><span class="flag">${flagFor(code)}</span><b>${esc(c.name)}</b></button>`}).join('');const ranked=[...alerts].sort((a,b)=>(['high','blocked'].includes(b.severity)?1:0)-(['high','blocked'].includes(a.severity)?1:0));const alertHtml=ranked.slice(0,5).map(a=>`<div class="alert-row ${['high','blocked'].includes(a.severity)?'high':''}"><span class="alert-mark"></span><div><b>${esc(a.title||a.message||'Supply alert')}</b><p>${esc(a.description||a.cause||'Review the affected plan and evidence.')}</p><button class="text-link" data-alert-event="${esc(a.event_id||'')}" data-alert-scenario="${esc(a.scenario_id||'')}" data-alert-id="${esc(a.id||'')}">${esc(a.action_label||a.recommended_action||'Review alert')} ↗</button></div><span class="alert-meta">${a.affected_shipments??a.affected_shipment_count??a.shipment_count??''} shipments</span></div>`).join('')||`<div class="empty"><b>All quiet for now</b>No active supply alerts.</div>`;
content.innerHTML=`${heading('Supply control tower','A live view of country readiness, shipment exposure, and upcoming deadlines.',`<button class="button" id="reset-demo">↺ Reset demo data</button><button class="button primary" id="generate-plan">＋ Generate plan</button>`)}${!state.boot.approved_scenario?`<div class="callout pending-plan"><strong>${pending?'A proposed plan is waiting for human review.':'No approved baseline is loaded.'}</strong> ${pending?'Review its evidence and record a named decision in Scenarios.':'Generate a plan to calculate shipments and milestones; it will appear as a proposal for review.'} <button class="text-link" data-nav="scenarios">${pending?'Review proposal →':'Open scenarios →'}</button></div>`:''}<div class="kpi-grid"><div class="kpi"><div class="kpi-top">Countries covered <span class="kpi-icon">◎</span></div><div class="kpi-value">${m.countries??jur.length}</div><div class="kpi-sub">Across this trial footprint</div></div><div class="kpi risk"><div class="kpi-top">Shipments at risk <span class="kpi-icon">↗</span></div><div class="kpi-value">${hasPlan?(m.shipments_at_risk??ships.filter(s=>s.risk_band==='at_risk').length):'—'}</div><div class="kpi-sub">${p.status==='proposed'?'Latest proposal':'At risk or blocked shipments'}</div></div><div class="kpi blocked"><div class="kpi-top">Blocked shipments <span class="kpi-icon">⊘</span></div><div class="kpi-value">${hasPlan?(m.blocked_shipments??ships.filter(s=>s.risk_band==='blocked').length):'—'}</div><div class="kpi-sub">Require a planning decision</div></div><div class="kpi"><div class="kpi-top">Deadlines · next 14 days <span class="kpi-icon">◷</span></div><div class="kpi-value">${hasPlan?(m.deadlines_14_days??0):'—'}</div><div class="kpi-sub">Upcoming operational milestones</div></div></div><div class="dashboard-grid"><section class="card"><div class="card-head"><div><h2>Country readiness</h2><p>${jur.length} jurisdictions in the current supply footprint</p></div><button class="text-link" data-nav="requirements">View requirements →</button></div><div class="country-grid">${tiles||'<div class="empty">No jurisdictions are in this dataset.</div>'}</div><div class="legend"><span><i></i>On track</span><span><i class="risk-dot"></i>At risk</span><span><i class="blocked-dot"></i>Blocked</span><span><i class="unknown-dot"></i>No shipment</span></div></section><section class="card"><div class="card-head"><div><h2>Priority alerts</h2><p>Ranked by shipment impact</p></div><button class="text-link" data-nav="scenarios">Review scenarios →</button></div><div class="alert-list">${alertHtml}</div></section></div><section class="card section-card"><div class="card-head"><div><h2>Shipment readiness</h2><p>${p.status==='proposed'?'Proposed plan · awaiting review':'Approved plan'} · ${esc(p.name||'No plan generated')}</p></div><button class="text-link" data-nav="scenarios">Open plan →</button></div>${shipTable(ships.slice(0,8))}</section><div class="footer-note">Evidence status is shown on each requirement. Synthetic records are planning assumptions and must be reviewed before operational use.</div>`;
$$('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));$$('.country-tile').forEach(b=>b.onclick=()=>{state.reqCountry=b.dataset.country;nav('requirements')});$('#generate-plan')?.addEventListener('click',generatePlan);$('#reset-demo')?.addEventListener('click',resetDemo);$$('[data-alert-event]').forEach(b=>b.onclick=()=>b.dataset.alertEvent?analyzeEvent(b.dataset.alertEvent):reviewAlert(b.dataset.alertScenario,b.dataset.alertId));}
function shipTable(rows){if(!rows.length)return `<div class="empty"><b>No shipments to display</b>Generate a plan to create country delivery schedules.</div>`;return `<div class="table-wrap"><table><thead><tr><th>Destination</th><th>Target delivery</th><th>Projected</th><th>Label group</th><th>Route</th><th>Readiness</th><th>Slack</th></tr></thead><tbody>${rows.map(s=>`<tr><td><span class="country-name"><span>${flagFor(s.country_code)}</span><strong>${esc(s.country_name||s.country_code)}</strong></span></td><td>${date(s.target_delivery)}</td><td>${date(s.projected_delivery)}</td><td>${esc(s.label_group_id||'—')}</td><td>${esc(s.route_name||'—')}</td><td>${badge(s.risk_band)}</td><td>${s.slack_days??'—'} days</td></tr>`).join('')}</tbody></table></div>`}
async function generatePlan(){try{const p=await api(`/api/trials/${encodeURIComponent(state.boot.trial.id)}/scenarios/generate`,{method:'POST',body:'{}'});state.boot.approved_scenario=p;await load();notify('Plan generated from the active dataset.')}catch(e){notify(e.message,'error')}}
async function resetDemo(){if(!confirm('Reset the local workspace to its demo fixture?'))return;try{state.boot=await api('/api/demo/reset',{method:'POST',body:JSON.stringify({fixture:'demo'})});state.scenario=state.boot.approved_scenario;state.comparison=null;state.assistantScenario='';render();notify('Demo fixture restored.')}catch(e){notify(e.message,'error')}}
async function ackAlert(id){try{await api(`/api/alerts/${encodeURIComponent(id)}/acknowledge`,{method:'POST',body:'{}'});await load();notify('Alert acknowledged.')}catch(e){notify(e.message,'error')}}
async function reviewAlert(scenarioId,alertId){if(scenarioId){try{const plan=await api(`/api/scenarios/${encodeURIComponent(scenarioId)}`);state.comparison=plan;state.boot.scenarios=[plan,...scenarios().filter(s=>s.id!==plan.id)];nav('scenarios')}catch(e){notify(e.message,'error')}return}await ackAlert(alertId)}
function renderRequirements(){const juris=countryList();if(!state.reqCountry&&juris.length)state.reqCountry=juris[0].iso_code||juris[0].id;const opts=juris.map(c=>`<option value="${esc(c.iso_code||c.id)}" ${state.reqCountry===(c.iso_code||c.id)?'selected':''}>${esc(c.name)}</option>`).join('');content.innerHTML=`${heading('Requirements & timeline','Search dated country rules, inspect the source evidence, and follow each shipment milestone.',`<button class="button" id="req-import">⇧ Import research</button>`)}<div class="toolbar" style="margin-bottom:15px"><label class="search"><input id="req-search" placeholder="Search requirements, languages, documents…" value="${esc(state.query)}" aria-label="Search requirements"></label><select class="select" id="req-country" aria-label="Country">${opts}</select><label class="field-label" style="margin:0 0 0 3px">As of</label><input class="input" id="req-date" type="date" value="${esc(state.reqDate)}"></div><div class="two-col"><section class="card"><div class="card-head"><div><h2 id="req-title">Country requirements</h2><p id="req-subtitle">Rules active on the selected date</p></div><span id="req-coverage"></span></div><div id="requirements-list"><div class="loading"><span class="spinner"></span>Loading requirements…</div></div><div class="card-head" style="margin-top:24px"><div><h2>Milestone timeline</h2><p>Permit filing through site delivery</p></div><select class="select" id="timeline-shipment" aria-label="Shipment"><option value="">Approved scenario</option>${(shipmentRows(state.boot.approved_scenario)).map(s=>`<option value="${esc(s.id)}">${esc(s.country_name)}</option>`).join('')}</select></div><div id="timeline-panel"></div></section><aside class="card evidence-panel"><h3>Source evidence</h3><div id="evidence-content" class="evidence-placeholder">Select a requirement to inspect its exact excerpt, source, effective dates, and review state.</div></aside></div>`;
$('#req-country').onchange=e=>{state.reqCountry=e.target.value;state.selectedRule=null;loadRequirements()};$('#req-date').onchange=e=>{state.reqDate=e.target.value;state.selectedRule=null;loadRequirements()};$('#req-search').oninput=e=>{state.query=e.target.value;drawRequirements()};$('#timeline-shipment').onchange=()=>drawTimeline($('#timeline-shipment').value);$('#req-import').onclick=()=>{state.importType='rules';nav('imports')};loadRequirements();drawTimeline('')}
async function loadRequirements(){const list=$('#requirements-list');if(!list)return;list.innerHTML='<div class="loading"><span class="spinner"></span>Loading requirements…</div>';try{const d=await api(`/api/jurisdictions/${encodeURIComponent(state.reqCountry)}/requirements?as_of=${encodeURIComponent(state.reqDate)}`);state.requirements=d.requirements||[];$('#req-title').textContent=`${d.country?.name||jurisdictionName(state.reqCountry)} requirements`;$('#req-subtitle').textContent=`Rules active as of ${date(d.as_of||state.reqDate)}`;$('#req-coverage').innerHTML=`${state.requirements.length} records`;drawRequirements()}catch(e){list.innerHTML=`<div class="empty"><b>Requirements unavailable</b>${esc(e.message)}</div>`}}
function jurisdictionName(code){return countryList().find(c=>(c.iso_code||c.id)===code)?.name||code}
function drawRequirements(){const list=$('#requirements-list');if(!list)return;const q=state.query.toLowerCase();const rows=state.requirements.filter(r=>!q||JSON.stringify(r).toLowerCase().includes(q));if(!rows.length){list.innerHTML=`<div class="empty"><b>No matching requirements</b>${state.requirements.length?'Try a different search.':'No rule records are available for this jurisdiction and date.'}</div>`;return}list.innerHTML=`<div class="table-wrap"><table><thead><tr><th>Requirement</th><th>Rule type</th><th>Effective from</th><th>As of selected date</th><th>Evidence</th><th>Review</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td><button class="text-link rule-select" data-index="${i}">${esc(r.requirement_key||r.rule_type||r.id||'Requirement')}</button><div style="color:#8b9898;font-size:9px;margin:3px 0 0 7px">${esc(valueText(r))}</div></td><td>${esc(pretty(r.rule_type||''))}</td><td>${date(r.effective_from)}</td><td>${r.future_effective?'Future effective':r.active===true?'Active on selected date':r.active===false?'Outside active period':'Date scope recorded'}</td><td>${r.source_url?`<a class="source-link" href="${esc(safeUrl(r.source_url))}" target="_blank" rel="noreferrer">${esc(r.source_tier||'Source')} ↗</a>`:'—'}</td><td>${badge(r.review_status||r.status||r.source_tier)}</td></tr>`).join('')}</tbody></table></div>`;$$('.rule-select',list).forEach(btn=>btn.onclick=()=>showEvidence(rows[Number(btn.dataset.index)]))}
function valueText(r){const v=r.value??r.value_json??r.notes??'';return typeof v==='object'?JSON.stringify(v):String(v)}
function showEvidence(r){state.selectedRule=r;const el=$('#evidence-content');if(!el)return;el.className='';el.innerHTML=`<div class="evidence-block"><div class="label">Requirement</div><div class="value"><b>${esc(r.requirement_key||r.rule_type||'Rule')}</b><br>${esc(valueText(r))}</div></div><div class="evidence-block"><div class="label">Source status</div><div class="value">${badge(r.review_status||r.status||'needs_review')} ${badge(r.source_tier||'unknown')}</div></div><div class="evidence-block"><div class="label">Jurisdiction · Rule type</div><div class="value">${esc(r.country_name||jurisdictionName(state.reqCountry))} · ${esc(pretty(r.rule_type||'—'))}</div></div><div class="evidence-block"><div class="label">Effective period</div><div class="value">${date(r.effective_from)}${r.effective_to?` — ${date(r.effective_to)}`:' onward'}</div></div><div class="evidence-block"><div class="label">Exact source excerpt</div><div class="value quote">${esc(r.source_excerpt||'No source excerpt was supplied for this record.')}</div></div><div class="evidence-block"><div class="label">Source document</div><div class="value">${r.source_url?`<a class="source-link" target="_blank" rel="noreferrer" href="${esc(safeUrl(r.source_url))}">${esc(r.source_title||r.source_url)} ↗</a>`:'No source URL recorded.'}</div></div><div class="evidence-block"><div class="label">Retrieved / verified</div><div class="value">${esc(r.retrieved_at||r.last_verified_at||'Not recorded')}</div></div>`}
function drawTimeline(shipmentId){const panel=$('#timeline-panel');if(!panel)return;const plan=state.boot.approved_scenario;let shipments=shipmentRows(plan);if(shipmentId)shipments=shipments.filter(s=>s.id===shipmentId);if(!shipments.length){panel.innerHTML='<div class="empty">No shipment milestones are available.</div>';return}const timeline=shipments.flatMap(s=>(s.milestones||[]).map(m=>({...m,country_name:s.country_name}))).sort((a,b)=>String(a.planned_date||'').localeCompare(String(b.planned_date||'')));panel.innerHTML=timeline.length?`<div class="timeline">${timeline.map(m=>`<div class="milestone"><div class="milestone-date">${date(m.projected_date||m.planned_date)}</div><div class="milestone-dot"></div><div><div class="milestone-name">${esc(m.label||pretty(m.type))}${m.country_name?` · ${esc(m.country_name)}`:''}</div><div class="milestone-sub">${m.duration_days??0} days${m.dependencies?.length?` · follows ${esc(m.dependencies.join(', '))}`:''}</div></div></div>`).join('')}</div>`:'<div class="empty">No milestones are recorded for this scenario.</div>'}
function renderScenarios(){const items=scenarios();const active=state.boot.approved_scenario;const proposed=items.filter(s=>s.status==='proposed'||s.approval_status==='proposed');const events=state.boot.events||[];const selected=state.comparison||proposed[0]||null;const actions=`<button class="button" id="calendar-btn" ${active?.status==='approved'?'':'disabled'}>▣ Approved calendar (.ics)</button>`;content.innerHTML=`${heading('Scenario review','Compare a proposed plan to the approved baseline, inspect every change, and record the human decision.',actions)}<div class="toolbar" style="margin-bottom:15px"><label class="field-label" style="margin:0">Baseline</label><select class="select" id="before-scenario">${items.map(s=>`<option value="${esc(s.id)}" ${(state.compareBefore||active?.id)===s.id?'selected':''}>${esc(scenarioName(s))} · ${esc(pretty(s.status||'approved'))}</option>`).join('')}</select><label class="field-label" style="margin:0 0 0 8px">Compare with</label><select class="select" id="after-scenario"><option value="">Choose a scenario…</option>${items.map(s=>`<option value="${esc(s.id)}" ${(state.compareAfter||selected?.id)===s.id?'selected':''}>${esc(scenarioName(s))} · ${esc(pretty(s.status||'approved'))}</option>`).join('')}</select><button class="button" id="compare-btn">Compare</button></div><div class="split-layout"><section class="card"><div class="card-head"><div><h2>Scenario comparison</h2><p>Plan dates, routes, label groups, and risk changes</p></div>${selected?badge(selected.status||selected.approval_status):''}</div><div id="comparison-panel">${selected?'<div class="loading"><span class="spinner"></span>Loading scenario comparison…</div>':'<div class="empty"><b>No proposal selected</b>Analyze a change event to create a proposed repair scenario.</div>'}</div></section><section class="card"><div class="card-head"><div><h2>Change events</h2><p>Analyze an event to generate an immutable proposal</p></div></div>${events.length?events.map(ev=>`<div class="repair-card"><div style="flex:1"><b>${esc(ev.title)}</b><p>${esc(ev.description||'')}</p><div class="pill-row">${badge(ev.event_type)}${ev.synthetic?badge('synthetic'):''}${ev.jurisdiction?`<span class="mini-pill">${esc(ev.jurisdiction)}</span>`:''}</div></div><button class="button small" data-analyze="${esc(ev.id)}">Analyze →</button></div>`).join(''):'<div class="empty"><b>No change events are available</b>Events will appear here when provided by the active dataset.</div>'}</section></div><div class="dashboard-grid"><section class="card section-card"><div class="card-head"><div><h2>Proposed shipments</h2><p id="scenario-caption">Select a scenario above to inspect its full schedule.</p></div></div><div id="scenario-shipments"></div></section><section class="card section-card"><div class="card-head"><div><h2>Label groups & split reasons</h2><p>Compatibility decisions from the planner</p></div></div><div id="label-groups"></div></section></div><section class="card section-card"><div class="card-head"><div><h2>Approval history</h2><p>Every approval and rejection is recorded with a person and note.</p></div><button class="text-link" data-nav="audit">Open audit history →</button></div><div id="approval-controls"></div></section>`;
$('#before-scenario').onchange=e=>state.compareBefore=e.target.value;$('#after-scenario').onchange=e=>state.compareAfter=e.target.value;$('#compare-btn').onclick=()=>{state.compareBefore=$('#before-scenario').value;state.compareAfter=$('#after-scenario').value;if(!active?.id){notify('A baseline is required before two scenarios can be compared.','warning');return}if(!state.compareAfter){notify('Choose a second scenario to compare.','warning');return}loadComparison(state.compareBefore,state.compareAfter)};$('#calendar-btn').onclick=()=>{if(active?.id)window.location.href=`/api/scenarios/${encodeURIComponent(active.id)}/calendar.ics`};$$('[data-analyze]').forEach(b=>{b.disabled=!active?.id;b.onclick=()=>analyzeEvent(b.dataset.analyze)});$$('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));if(selected){state.comparison=selected;renderSelectedScenario(selected);if(active?.id&&selected.id!==active.id)loadComparison(active.id,selected.id);else loadScenarioDetails(selected.id)}else renderSelectedScenario(active)}
async function loadScenarioDetails(id){const panel=$('#comparison-panel');if(panel)panel.innerHTML='<div class="loading"><span class="spinner"></span>Loading scenario…</div>';try{const plan=await api(`/api/scenarios/${encodeURIComponent(id)}`);state.comparison=plan;state.boot.scenarios=[plan,...scenarios().filter(s=>s.id!==plan.id)];renderSelectedScenario(plan);if(panel)panel.innerHTML=`<div class="callout">${plan.status==='proposed'?'This plan has no approved baseline yet. A named reviewer can inspect the complete schedule below and record a decision.':'This scenario is selected for review.'}</div>`}catch(e){if(panel)panel.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function renderSelectedScenario(plan){if(!plan)return;$('#scenario-caption')&&($('#scenario-caption').textContent=`${scenarioName(plan)} · ${plan.shipments?.length||0} destination shipments`);$('#scenario-shipments')&&( $('#scenario-shipments').innerHTML=shipTable(shipmentRows(plan)));const groups=plan.label_groups||[];$('#label-groups')&&( $('#label-groups').innerHTML=groups.length?groups.map(g=>`<div class="repair-card"><div style="flex:1"><b>${esc(g.id||'Label group')} · ${(g.country_codes||[]).length} countries</b><p>${esc((g.country_codes||[]).map(jurisdictionName).join(', '))}</p><div class="pill-row">${(g.languages||[]).map(l=>`<span class="mini-pill">${esc(l)}</span>`).join('')}<span class="mini-pill">${g.estimated_pages??'—'} pages</span></div>${(g.reasons||[]).length?`<p class="repair-tradeoff">Split / compatibility reasons: ${esc(g.reasons.map(r=>typeof r==='string'?r:r.detail||r.reason||JSON.stringify(r)).join('; '))}</p>`:''}</div></div>`).join(''):'<div class="empty">No label group details are available.</div>');const ctrl=$('#approval-controls');if(ctrl){if(plan.status==='proposed'||plan.approval_status==='proposed')ctrl.innerHTML=`<div class="callout"><strong>Human review required.</strong> This proposal does not change the approved baseline until a named reviewer records a decision.</div><button class="button primary" id="approve-proposal" data-approve="${esc(plan.id)}">Approve proposal</button> <button class="button danger" id="reject-proposal">Reject proposal</button>`;else ctrl.innerHTML=`<div class="callout">Current status: <strong>${esc(pretty(plan.status||plan.approval_status||'unknown'))}</strong>${plan.approver?` · Recorded by ${esc(plan.approver)}`:''}${plan.approval_note||plan.note?` · “${esc(plan.approval_note||plan.note)}”`:''}</div>`;$('#approve-proposal')?.addEventListener('click',()=>decisionDialog(plan.id,'approve'));$('#reject-proposal')?.addEventListener('click',()=>decisionDialog(plan.id,'reject'))}}
async function loadComparison(before,after){const panel=$('#comparison-panel');if(!panel)return;panel.innerHTML='<div class="loading"><span class="spinner"></span>Comparing scenarios…</div>';try{const [data,afterPlan]=await Promise.all([api(`/api/scenarios/${encodeURIComponent(before)}/compare/${encodeURIComponent(after)}`),api(`/api/scenarios/${encodeURIComponent(after)}`)]);state.comparison=afterPlan;state.boot.scenarios=[afterPlan,...scenarios().filter(s=>s.id!==afterPlan.id)];const changes=data.changes||[];const changedCountries=new Set(changes.map(c=>c.country_code).filter(Boolean));if(typeof data.summary==='object'&&data.summary){const sm=data.summary;data.summary=`${sm.changed_countries??changes.length} countries changed · at-risk shipments ${sm.before?.shipments_at_risk??'—'} → ${sm.after?.shipments_at_risk??'—'} · cost proxy Δ ${sm.cost_delta??'—'}`};if(Array.isArray(data.causal_chain))data.causal_chain=data.causal_chain.filter(c=>!c.country_code||changedCountries.has(c.country_code)).flatMap(c=>Array.isArray(c.steps)?c.steps:[typeof c==='string'?c:c.label||c.description||'']);panel.innerHTML=`<div class="compare-banner"><div class="compare-side"><span class="circle">✓</span><div><small>BASELINE PLAN</small><b>${esc(scenarioName(planById(before)))}</b></div></div><div class="compare-arrow">→</div><div class="compare-side proposal"><span class="circle">✦</span><div><small>SCENARIO</small><b>${esc(scenarioName(afterPlan))}</b></div></div></div><div class="callout">${esc(data.summary||`${changes.length} country-level changes identified.`)}</div>${data.causal_chain?.length?`<div class="causal-chain"><h3>Cause and effect</h3><div class="chain-items">${data.causal_chain.map((c,i)=>`${i?'<span class="chain-arrow">→</span>':''}<span class="chain-item">${esc(typeof c==='string'?c:c.label||c.description||JSON.stringify(c))}</span>`).join('')}</div></div>`:''}<div class="table-wrap"><table><thead><tr><th>Destination</th><th>Before → after</th><th>Route / label group</th><th>Shipment impact</th><th>Changed milestones</th></tr></thead><tbody>${changes.length?changes.map(c=>`<tr><td><strong>${esc(c.country_name||c.country_code)}</strong></td><td>${date(c.before?.projected_delivery)} → ${date(c.after?.projected_delivery)}</td><td>${esc(c.before?.route_name||c.before?.route_id||'—')} / ${esc(c.before?.label_group_id||'—')} → ${esc(c.after?.route_name||c.after?.route_id||'—')} / ${esc(c.after?.label_group_id||'—')}</td><td>${badge(c.after?.risk_band||'—')} · ${c.after?.slack_days??'—'} days slack</td><td>${esc((c.changed_milestones||[]).map(m=>typeof m==='string'?m:(m.label||m.type||m.id)).join(', ')||'—')}</td></tr>`).join(''):'<tr><td colspan="5">No material differences found.</td></tr>'}</tbody></table></div>${repairChoices(afterPlan)}`;renderSelectedScenario(afterPlan);$$('[data-repair]').forEach(b=>b.onclick=()=>analyzeEvent(b.dataset.event,{repair:b.dataset.repair,parent:after}))}catch(e){panel.innerHTML=`<div class="empty"><b>Comparison could not be loaded</b>${esc(e.message)}</div>`}}
function repairChoices(plan){const options=plan?.repair_options||[];if(!options.length)return '';return `<div style="margin-top:15px"><div class="eyebrow">Repair options</div>${options.map(o=>`<div class="repair-card"><div style="flex:1"><b>${esc(o.title)}</b><p>${esc(o.description||'')}</p>${o.tradeoffs?`<p class="repair-tradeoff">Trade-off: ${esc(o.tradeoffs)}</p>`:''}</div><button class="button small" data-repair="${esc(o.id)}" data-event="${esc(o.event_id||plan.applied_event_ids?.[0]||'')}">Create repair</button></div>`).join('')}</div>`}
async function analyzeEvent(id,extra={}){if(!id){notify('This alert does not include an event to analyze.','warning');return}$$('[data-repair],[data-approve],[data-analyze]').forEach(b=>{b.disabled=true});const panel=$('#comparison-panel');if(panel)panel.innerHTML='<div class="loading"><span class="spinner"></span>Recalculating proposal…</div>';try{const plan=await api(`/api/change-events/${encodeURIComponent(id)}/analyze`,{method:'POST',body:JSON.stringify({parent_scenario_id:extra.parent||state.boot.approved_scenario?.id,...(extra.repair?{repair:extra.repair}:{})})});state.boot.scenarios=[plan,...scenarios().filter(s=>s.id!==plan.id)];state.comparison=plan;$('#scenario-count').textContent=scenarios().length;notify('A proposed scenario is ready for review.');nav('scenarios')}catch(e){if(state.view==='scenarios')renderScenarios();notify(e.message,'error')}}
function decisionDialog(id,action){showModal(`<div class="modal-head"><div><h2>${action==='approve'?'Approve proposed scenario':'Reject proposed scenario'}</h2><p>Record the responsible person and a decision note in the audit trail.</p></div><button class="close-button" data-close aria-label="Close">×</button></div><label class="field-label" for="decision-name">Reviewer name</label><input class="input" id="decision-name" placeholder="Your name" style="width:100%"><label class="field-label" for="decision-note">Decision note</label><textarea class="textarea" id="decision-note" placeholder="Why is this decision appropriate? Include relevant trade-offs."></textarea><div class="modal-actions"><button class="button" data-close>Cancel</button><button class="button ${action==='approve'?'primary':'danger'}" id="decision-submit">${action==='approve'?'Approve scenario':'Reject scenario'}</button></div>`);$('#decision-submit').onclick=async()=>{const approver=$('#decision-name').value.trim(),note=$('#decision-note').value.trim();if(!approver||!note){notify('Enter your name and a decision note.','warning');return}try{const p=await api(`/api/scenarios/${encodeURIComponent(id)}/${action}`,{method:'POST',body:JSON.stringify({approver,note})});closeModal();state.comparison=p;await load();nav('scenarios');notify(`Scenario ${action==='approve'?'approved':'rejected'} and recorded.`)}catch(e){notify(e.message,'error')}}}
function renderAssistant(){const items=scenarios();const active=state.assistantScenario||state.comparison?.id||state.boot.approved_scenario?.id;const plan=planById(active)||state.boot.approved_scenario;const risky=shipmentRows(plan).find(s=>s.risk_band==='at_risk'||s.risk_band==='blocked');const promptRisk=risky?`Why is ${risky.country_name||risky.country_code} at risk?`:'Explain the highest-risk shipment in this scenario.';content.innerHTML=`${heading('Planner assistant','Ask why a shipment is at risk or explore a repair. Answers use stored plans and cited source evidence.',`<span class="mini-pill">Read-only planning tools</span>`)}<div class="chat-layout"><section class="card chat-card"><div class="card-head"><div><h2>Supply planning assistant</h2><p>${esc(state.boot.trial?.name||'Current trial')} · context: ${esc(plan?.name||'No scenario selected')}</p></div><label class="field-label" style="margin:0"><span class="sr-only">Assistant scenario</span><select id="assistant-scenario" class="select" aria-label="Scenario context">${items.map(s=>`<option value="${esc(s.id)}" ${s.id===active?'selected':''}>${esc(scenarioName(s))} · ${esc(pretty(s.status||'approved'))}</option>`).join('')}</select></label></div><div id="chat-messages" class="chat-messages">${state.chat.length?state.chat.map(chatMessage).join(''):`<div class="chat-msg">I can explain shipment risk using the selected scenario and source records. Legal claims will include stored citations and evidence status.</div>`}</div><div class="suggestions">${[promptRisk,'What if Japan receives a separate label?','Which requirements are still synthetic?'].map(q=>`<button class="suggestion">${esc(q)}</button>`).join('')}</div><form id="chat-form" class="chat-input"><input id="chat-question" placeholder="Ask about this plan…" aria-label="Ask planner assistant" required><button class="button primary" type="submit">Ask ↗</button></form></section></div>`;$('#assistant-scenario').onchange=e=>{state.assistantScenario=e.target.value;renderAssistant()};$$('.suggestion').forEach(b=>b.onclick=()=>askAssistant(b.textContent));$('#chat-form').onsubmit=e=>{e.preventDefault();askAssistant($('#chat-question').value)};$$('[data-chat-suggestion]').forEach(b=>b.onclick=()=>askAssistant(b.dataset.chatSuggestion))}
function chatMessage(m){return `<div class="chat-msg ${m.role==='user'?'user':''}">${esc(m.text)}${m.citations?.length?`<div>${m.citations.map(c=>`<a class="cite" href="${esc(safeUrl(c.url))}" target="_blank" rel="noreferrer">${esc(c.title||'Source')} · ${esc(c.status||'source')} ↗</a>`).join('')}</div>`:''}${m.suggestions?.length?`<div>${m.suggestions.map(q=>`<button class="suggestion" data-chat-suggestion="${esc(q)}">${esc(q)}</button>`).join('')}</div>`:''}</div>`}
async function askAssistant(question){const q=String(question||'').trim();if(!q)return;state.chat.push({role:'user',text:q});renderAssistant();try{const answer=await api('/api/assistant/query',{method:'POST',body:JSON.stringify({question:q,scenario_id:state.assistantScenario||state.comparison?.id||state.boot.approved_scenario?.id,trial_id:state.boot.trial?.id})});state.chat.push({role:'assistant',text:answer.answer||'No answer was returned.',citations:answer.citations||[],suggestions:answer.suggested_questions||[]})}catch(e){state.chat.push({role:'assistant',text:`I couldn't retrieve a grounded answer: ${e.message}`,citations:[]})}renderAssistant()}
function renderImports(){const sources=collectSources();content.innerHTML=`${heading('Data & research','Import teammate research, inspect source changes, or replace the active dataset. Preview validation before committing.',`<button class="button" id="audit-import-link">◷ Recent import activity</button>`)}<div class="split-layout"><section class="card"><div class="card-head"><div><h2>Research rule import</h2><p>One atomic regulatory requirement per record</p></div><span class="mini-pill">JSON</span></div><div class="callout"><strong>Required source fields</strong> Jurisdiction, rule type, requirement key, effective date, source URL, title, exact excerpt, retrieved date, source tier, confidence, and review status. Verified records must cite non-synthetic sources.</div><label class="field-label" for="rules-file">Choose a research JSON file</label><div class="file-drop"><input id="rules-file" type="file" accept=".json,application/json"><div>or paste an array of atomic records below</div></div><textarea class="textarea" id="rules-json" placeholder='[{"jurisdiction":"<ISO code>","rule_type":"<rule type>","requirement_key":"<key>","operator":"<supported operator>","value":null,"effective_from":"YYYY-MM-DD","source_url":"https://…","source_title":"<official source title>","source_excerpt":"<exact cited text>","retrieved_at":"YYYY-MM-DDTHH:mm:ssZ","source_tier":"official","confidence":1,"review_status":"needs_review"}]'></textarea><div class="modal-actions"><button class="button primary" id="preview-rules">Validate & preview</button></div><div id="rule-preview"></div></section><section class="card"><div class="card-head"><div><h2>Replace active dataset</h2><p>Load a complete fixture, validate it, then commit it as the new source of planning inputs.</p></div></div><div class="callout">Dataset replacement changes active trial, countries, products, sources, events, and planning inputs. Preview the validation report before you commit.</div><label class="field-label" for="dataset-file">Choose a complete dataset JSON</label><div class="file-drop"><input id="dataset-file" type="file" accept=".json,application/json"></div><textarea class="textarea" id="dataset-json" placeholder="Paste the full dataset JSON here…"></textarea><div class="modal-actions"><button class="button primary" id="preview-dataset">Validate dataset</button></div><div id="dataset-preview"></div></section></div><section class="card section-card"><div class="card-head"><div><h2>Check a source snapshot</h2><p>Compare newly collected source text with its prior snapshot. Network collection is not required.</p></div></div>${sources.length?`<label class="field-label" for="snapshot-source">Source document</label><select class="select" id="snapshot-source">${sources.map(s=>`<option value="${esc(s.id)}">${esc(s.title||s.canonical_url||s.url||s.id)}</option>`).join('')}</select>`:'<div class="empty"><b>No source documents are recorded</b>Import source documents with the active dataset before checking for changes.</div>'}<label class="field-label" for="snapshot-content">New source content</label><textarea id="snapshot-content" class="textarea" placeholder="Paste the newly retrieved source text here…"></textarea><button class="button primary" id="check-snapshot" ${sources.length?'':'disabled'} style="margin-top:12px">Compare snapshot</button><div id="snapshot-result"></div></section><div class="card section-card"><div class="card-head"><div><h2>Active dataset</h2><p>Currently loaded trial and source footprint</p></div><button class="button small" id="refresh-dataset">Refresh summary</button></div><div id="dataset-summary" class="callout">${esc(state.boot.dataset_summary?.description||state.boot.dataset_summary?.name||JSON.stringify(state.boot.dataset_summary||{}))}</div></div>`;
$('#rules-file').onchange=e=>readFileTo(e.target.files[0],'rules-json');$('#dataset-file').onchange=e=>readFileTo(e.target.files[0],'dataset-json');$('#preview-rules').onclick=previewRules;$('#preview-dataset').onclick=previewDataset;$('#refresh-dataset').onclick=loadDatasetSummary;$('#audit-import-link').onclick=()=>nav('audit');$('#check-snapshot').onclick=checkSnapshot;}
function collectSources(){const d=state.dataset||{};const sources=d.source_documents||d.sources||[];const rules=d.rules||d.rule_versions||[];const combined=[...sources,...rules.map(r=>r.source_document).filter(Boolean)];const seen=new Set();return combined.filter(s=>s?.id&&!seen.has(s.id)&&seen.add(s.id))}
async function checkSnapshot(){const box=$('#snapshot-result');const source_id=$('#snapshot-source')?.value,content=$('#snapshot-content')?.value;if(!source_id||!content?.trim()){notify('Choose a source and paste its retrieved content.','warning');return}box.innerHTML='<div class="loading"><span class="spinner"></span>Comparing source snapshot…</div>';try{const data=await api('/api/sources/snapshot',{method:'POST',body:JSON.stringify({source_id,content})});box.innerHTML=`<div class="callout"><strong>Snapshot compared</strong><br>Hash: ${esc(data.hash||data.content_hash||'—')}<pre style="white-space:pre-wrap;font:11px 'DM Sans'">${esc(JSON.stringify(data.diff||data.change_diff||data,null,2))}</pre></div>`}catch(e){box.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function readFileTo(file,id){if(!file)return;const reader=new FileReader();reader.onload=()=>{$('#'+id).value=String(reader.result||'')};reader.onerror=()=>notify('Could not read the selected file.','error');reader.readAsText(file)}
function parseText(id){try{return JSON.parse($('#'+id).value)}catch(e){throw new Error(`The JSON could not be parsed: ${e.message}`)}}
async function previewRules(){const target=$('#rule-preview');target.innerHTML='<div class="loading"><span class="spinner"></span>Validating records…</div>';try{const records=parseText('rules-json');if(!Array.isArray(records))throw new Error('Research rules must be a JSON array.');const result=await api('/api/rules/import/preview',{method:'POST',body:JSON.stringify({records})});state.preview=result;target.innerHTML=previewCard(result,'rules');}catch(e){target.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
async function previewDataset(){const target=$('#dataset-preview');target.innerHTML='<div class="loading"><span class="spinner"></span>Validating dataset…</div>';try{const dataset=parseText('dataset-json');const result=await api('/api/datasets/import/preview',{method:'POST',body:JSON.stringify({dataset})});state.datasetPreview=result;target.innerHTML=previewCard(result,'dataset')}catch(e){target.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function previewCard(result,kind){const errors=result.errors||[];const valid=result.valid!==false&&!errors.length;return `<div class="card" style="margin-top:14px;border-color:${valid?'#cce2d5':'#eed0ca'}"><div class="card-head"><div><h2>${valid?'Preview ready':'Validation needs attention'}</h2><p>${kind==='rules'?`${result.records?.length??0} rule records received`:'Dataset validation report'}</p></div>${badge(valid?'ready':'needs_review')}</div>${errors.length?`<ul style="font-size:10px;color:#a04e48;line-height:1.7">${errors.map(e=>`<li>${esc(typeof e==='string'?e:JSON.stringify(e))}</li>`).join('')}</ul>`:'<div class="callout">No validation errors reported. Review the diff before committing.</div>'}<div class="callout"><strong>Change preview</strong><pre style="white-space:pre-wrap;font:10px 'DM Sans';margin:7px 0">${esc(JSON.stringify(result.diff||{},null,2))}</pre></div>${valid?`<label class="field-label">Reviewer name</label><input class="input" id="reviewer-${kind}" placeholder="Name of reviewer"><button class="button primary" style="margin-top:12px" data-commit="${kind}">Commit ${kind==='rules'?'research import':'dataset replacement'}</button>`:''}</div>`}
async function commitPreview(kind){const preview=kind==='rules'?state.preview:state.datasetPreview;const reviewer=$(`#reviewer-${kind}`)?.value.trim();if(!preview?.preview_id){notify('Preview expired or unavailable. Run validation again.','warning');return}if(!reviewer){notify('Enter a reviewer name to commit this import.','warning');return}try{const endpoint=kind==='rules'?'/api/rules/import/commit':'/api/datasets/import/commit';const result=await api(endpoint,{method:'POST',body:JSON.stringify({preview_id:preview.preview_id,reviewer})});if(kind==='rules'){$('#rule-preview').innerHTML=`<div class="callout"><strong>Research import committed.</strong> ${esc(JSON.stringify(result))}</div>`;notify('Research import committed.')}else{state.reqCountry='';state.reqDate='';notify('Dataset import committed.');await load()}}catch(e){notify(e.message,'error')}}
async function loadDatasetSummary(){try{const d=await api('/api/dataset');$('#dataset-summary').textContent=`${d.trial?.name||d.name||'Loaded dataset'} · ${(d.jurisdictions||d.countries||[]).length} jurisdictions · source records ${(d.rules||[]).length}`;notify('Active dataset details refreshed.')}catch(e){notify(e.message,'error')}}
async function renderAudit(){content.innerHTML=`${heading('Audit history','A trace of imports, plan generation, scenario analysis, and human decisions.',`<button class="button" id="audit-export">⇩ Export JSON</button><button class="button" id="audit-refresh">↻ Refresh history</button>`)}<section class="card"><div class="card-head"><div><h2>Workspace activity</h2><p>Recorded actions from the local supply workspace</p></div></div><div id="audit-list"><div class="loading"><span class="spinner"></span>Loading audit history…</div></div></section>`;$('#audit-refresh').onclick=renderAudit;$('#audit-export').onclick=downloadAudit;try{const data=await api('/api/audit');const events=data.events||[];$('#audit-list').innerHTML=events.length?`<div class="table-wrap"><table><thead><tr><th>When</th><th>Action</th><th>Actor</th><th>Details</th><th>Reference</th></tr></thead><tbody>${events.map(e=>`<tr><td>${esc(e.created_at||e.timestamp||e.at||'—')}</td><td>${badge(e.event_type||e.action||'activity')}</td><td>${esc(e.actor||e.approver||e.reviewer||'System')}</td><td>${esc(e.note||e.description||e.details||'—')}</td><td>${esc(e.scenario_id||e.preview_id||e.entity_id||'—')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><b>No audit events yet</b>Generated plans, imports, and scenario decisions will appear here.</div>'}catch(e){$('#audit-list').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
async function downloadAudit(){try{const data=await api('/api/audit');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='cleared-for-takeoff-audit.json';a.click();URL.revokeObjectURL(url)}catch(e){notify(e.message,'error')}}
function showModal(html){const root=$('#dialog-root');root.innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true">${html}</div></div>`;$$('[data-close]',root).forEach(b=>b.onclick=closeModal);$('.modal-backdrop',root).onclick=e=>{if(e.target===e.currentTarget)closeModal()}}
function closeModal(){$('#dialog-root').innerHTML=''}
document.addEventListener('click',e=>{const b=e.target.closest('[data-commit]');if(b)commitPreview(b.dataset.commit)});
$$('.nav-item').forEach(b=>b.addEventListener('click',()=>nav(b.dataset.view)));$('#refresh-btn').addEventListener('click',load);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});load();

// Human evidence review is intentionally separate from plan approval.
function showEvidenceWithReview(r){state.selectedRule=r;const el=$('#evidence-content');if(!el)return;const canVerify=r.source_tier!=='synthetic';el.className='';el.innerHTML=`<div class="evidence-block"><div class="label">Requirement</div><div class="value"><b>${esc(r.requirement_key||r.rule_type||'Rule')}</b><br>${esc(valueText(r))}</div></div><div class="evidence-block"><div class="label">Source status</div><div class="value">${badge(r.review_status||'needs_review')} ${badge(r.source_tier||'unknown')}</div></div><div class="evidence-block"><div class="label">Effective period</div><div class="value">${date(r.effective_from)}${r.effective_to?` — ${date(r.effective_to)}`:' onward'}</div></div><div class="evidence-block"><div class="label">Exact source excerpt</div><div class="value quote">${esc(r.source_excerpt||'No source excerpt supplied.')}</div></div><div class="evidence-block"><div class="label">Source document</div><div class="value">${r.source_url?`<a class="source-link" target="_blank" rel="noreferrer" href="${esc(safeUrl(r.source_url))}">${esc(r.source_title||r.source_url)} ↗</a>`:'No source URL recorded.'}</div></div><div class="evidence-block"><div class="label">Human review</div><input class="input" id="rule-reviewer" placeholder="Reviewer name" style="width:100%"><textarea class="textarea" id="rule-review-note" placeholder="Review note"></textarea><div class="modal-actions"><button class="button primary" data-rule-status="verified" ${canVerify?'':'disabled'}>Verify</button><button class="button" data-rule-status="needs_review">Keep in review</button><button class="button danger" data-rule-status="retired">Retire</button></div>${canVerify?'':'<small>Synthetic evidence cannot be verified. Import a cited source first.</small>'}</div>`;$$('[data-rule-status]',el).forEach(b=>b.onclick=()=>reviewRule(r.id,b.dataset.ruleStatus))}
showEvidence=showEvidenceWithReview;
async function reviewRule(id,status){const reviewer=$('#rule-reviewer').value.trim(),note=$('#rule-review-note').value.trim();if(!reviewer||!note){notify('Enter a reviewer name and review note.','warning');return}try{await api(`/api/rules/${encodeURIComponent(id)}/review`,{method:'POST',body:JSON.stringify({reviewer,note,status})});await loadRequirements();notify('Review recorded. A proposed plan is ready for review.')}catch(e){notify(e.message,'error')}}

const renderAssistantBase=renderAssistant;
renderAssistant=()=>{renderAssistantBase();const pill=$('.page-heading .mini-pill');if(pill)pill.textContent=`${state.boot.assistant_provider||'local'} · read-only`};

const renderImportsBase=renderImports;
renderImports=()=>{renderImportsBase();const input=$('#rules-file');input.multiple=true;input.accept='.json,.csv,application/json,text/csv';const fileLabel=$('label[for="rules-file"]');if(fileLabel)fileLabel.textContent='Choose one or more research JSON or CSV files';input.onchange=()=>loadRuleFiles([...input.files]);const card=$('#dataset-file').closest('section');card.querySelector('.callout').insertAdjacentHTML('afterend','<div class="callout"><strong>One complete workspace at a time.</strong> A dataset already contains every country, route, rule, and trial input. Use the multi-file research importer for country-by-country contributions.</div>');content.insertAdjacentHTML('beforeend',`<section class="card section-card"><div class="card-head"><div><h2>Research templates</h2><p>Start with the schema or a working export.</p></div></div><div class="modal-actions"><a class="button" href="/api/dataset" target="_blank">Current dataset JSON</a><a class="button" href="/api/templates/research.csv" target="_blank">Research CSV template</a><a class="button" href="/api/templates/research-rule.schema.json" target="_blank">Rule schema</a><a class="button" href="/api/templates/dataset.schema.json" target="_blank">Dataset schema</a></div></section><section class="card section-card"><div class="card-head"><div><h2>Source registry</h2><p>Register official pages and collect a new snapshot on demand.</p></div><button class="button" id="refresh-sources">Refresh</button></div><div class="toolbar"><input class="input" id="source-title" placeholder="Source title"><input class="input" id="source-url" placeholder="https://official.example/page"><select class="select" id="source-adapter"><option value="generic">Generic page</option><option value="ecfr">eCFR</option><option value="eurlex">EUR-Lex</option></select><button class="button primary" id="add-source">Add source</button></div><div id="source-registry"><div class="loading"><span class="spinner"></span>Loading sources…</div></div></section>`);$('#refresh-sources').onclick=loadSourceRegistry;$('#add-source').onclick=addSource;loadSourceRegistry()};
async function loadRuleFiles(files){try{const groups=await Promise.all(files.map(async file=>{const text=await file.text();return file.name.toLowerCase().endsWith('.csv')?csvRecords(text):JSON.parse(text)}));const records=groups.flat();if(!records.every(r=>r&&typeof r==='object'&&!Array.isArray(r)))throw new Error('Every file must contain rule records.');$('#rules-json').value=JSON.stringify(records,null,2);notify(`${records.length} records loaded from ${files.length} files.`)}catch(e){notify(`Could not combine files: ${e.message}`,'error')}}
function csvRecords(text){const rows=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'&&quote&&n==='"'){cell+='"';i++}else if(c==='"')quote=!quote;else if(c===','&&!quote){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&n==='\n')i++;row.push(cell);if(row.some(v=>v!==''))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(v=>v!==''))rows.push(row);const headers=rows.shift()||[];return rows.map(values=>Object.fromEntries(headers.map((h,i)=>[h.trim(),parseCsvValue(values[i]||'')])))}
function parseCsvValue(value){const v=value.trim();if(v==='')return null;if(v==='true'||v==='false')return v==='true';if(!Number.isNaN(Number(v)))return Number(v);if((v.startsWith('[')||v.startsWith('{'))){try{return JSON.parse(v)}catch{}}return v}
async function loadSourceRegistry(){const box=$('#source-registry');if(!box)return;try{const data=await api('/api/sources');box.innerHTML=data.sources.length?data.sources.map(s=>`<div class="repair-card"><div style="flex:1"><b>${esc(s.title)}</b><p>${esc(s.url)}</p><div class="pill-row">${badge(s.adapter||'generic')}${s.jurisdiction?badge(s.jurisdiction):''}</div></div><button class="button small" data-check-source="${esc(s.id)}">Check now</button></div>`).join(''):'<div class="empty">No sources registered yet.</div>';$$('[data-check-source]',box).forEach(b=>b.onclick=()=>checkRegisteredSource(b.dataset.checkSource,b))}catch(e){box.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
async function addSource(){const title=$('#source-title').value.trim(),url=$('#source-url').value.trim(),adapter=$('#source-adapter').value;try{await api('/api/sources',{method:'POST',body:JSON.stringify({title,url,adapter})});await loadSourceRegistry();notify('Source registered.')}catch(e){notify(e.message,'error')}}
async function checkRegisteredSource(id,button){button.disabled=true;button.textContent='Checking…';try{const result=await api(`/api/sources/${encodeURIComponent(id)}/check`,{method:'POST',body:'{}'});notify(result.changed?'Source changed; human review is required.':'Snapshot recorded; no change detected.');await loadSourceRegistry()}catch(e){notify(e.message,'error');button.disabled=false;button.textContent='Check now'}}

const renderOverviewBase=renderOverview;
renderOverview=()=>{renderOverviewBase();const plans=[state.boot.approved_scenario,...scenarios().filter(s=>s.id!==state.boot.approved_scenario?.id)].filter(Boolean);if(!state.calendarScenario||!plans.some(p=>p.id===state.calendarScenario))state.calendarScenario=plans[0]?.id;const anchor=$('.footer-note');if(!anchor)return;anchor.insertAdjacentHTML('beforebegin',`<section class="card section-card calendar-card"><div class="card-head"><div><h2>Supply timeline calendar</h2><p>Projected milestones update with the selected scenario.</p></div><div class="toolbar"><select class="select" id="calendar-scenario">${plans.map(p=>`<option value="${esc(p.id)}" ${p.id===state.calendarScenario?'selected':''}>${esc(scenarioName(p))} · ${esc(pretty(p.status))}</option>`).join('')}</select><a class="button" id="calendar-ics">Export full timeline (.ics)</a></div></div><div id="calendar-panel"></div></section>`);$('#calendar-scenario').onchange=e=>{state.calendarScenario=e.target.value;state.calendarMonth='';drawCalendar()};drawCalendar()};
function calendarPlan(){return state.comparison?.id===state.calendarScenario?state.comparison:(planById(state.calendarScenario)||state.boot.approved_scenario)}
function scenarioMilestones(plan){return shipmentRows(plan).flatMap(s=>(s.milestones||[]).map(m=>({...m,country_code:s.country_code,country_name:s.country_name,shipment_id:s.id,risk_band:s.risk_band,slack_days:s.slack_days}))).sort((a,b)=>milestoneDate(a).localeCompare(milestoneDate(b)))}
function milestoneDate(m){return m.projected_date||m.planned_date||''}
function drawCalendar(){const panel=$('#calendar-panel'),plan=calendarPlan();if(!panel||!plan)return;const events=scenarioMilestones(plan);const first=events.find(e=>milestoneDate(e))?.projected_date||plan.as_of;let month=state.calendarMonth?new Date(state.calendarMonth+'T00:00:00'):new Date(first.slice(0,7)+'-01T00:00:00');state.calendarMonth=`${month.getFullYear()}-${String(month.getMonth()+1).padStart(2,'0')}-01`;const year=month.getFullYear(),mi=month.getMonth(),start=new Date(year,mi,1),days=new Date(year,mi+1,0).getDate(),offset=(start.getDay()+6)%7;const byDay=new Map();events.forEach(e=>{const key=milestoneDate(e);if(key?.startsWith(state.calendarMonth.slice(0,7))){const day=Number(key.slice(8,10));byDay.set(day,[...(byDay.get(day)||[]),e])}});const cells=[...Array(offset)].map(()=>'<div class="calendar-day outside"></div>');for(let day=1;day<=days;day++){const entries=byDay.get(day)||[];cells.push(`<div class="calendar-day ${plan.as_of===`${state.calendarMonth.slice(0,8)}${String(day).padStart(2,'0')}`?'today':''}"><span class="calendar-number">${day}</span>${entries.slice(0,4).map(e=>`<button class="calendar-event ${esc(e.risk_band||'')}" data-calendar-event="${esc(e.shipment_id+'|'+e.id)}"><b>${esc(e.country_code)}</b> ${esc(e.label||pretty(e.type))}</button>`).join('')}${entries.length>4?`<small>+${entries.length-4} more</small>`:''}</div>`)}panel.innerHTML=`<div class="calendar-toolbar"><button class="icon-button" id="calendar-prev" aria-label="Previous month">‹</button><h3>${month.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</h3><button class="icon-button" id="calendar-next" aria-label="Next month">›</button><span class="calendar-legend"><i></i>On track <i class="watch"></i>At risk <i class="late"></i>Blocked</span></div><div class="calendar-weekdays">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-grid">${cells.join('')}</div><div class="calendar-foot">Planning date: ${date(plan.as_of)} · ${events.length} milestones · Select a milestone to add it to Google Calendar or Outlook.</div>`;$('#calendar-prev').onclick=()=>moveCalendar(-1);$('#calendar-next').onclick=()=>moveCalendar(1);$$('[data-calendar-event]',panel).forEach(b=>b.onclick=()=>openCalendarEvent(b.dataset.calendarEvent));const ics=$('#calendar-ics');ics.href=`/api/scenarios/${encodeURIComponent(plan.id)}/calendar.ics`;ics.classList.toggle('disabled',plan.status!=='approved');ics.onclick=plan.status==='approved'?null:e=>{e.preventDefault();notify('Approve this scenario before exporting its full calendar.','warning')}}
function moveCalendar(delta){const d=new Date(state.calendarMonth+'T00:00:00');d.setMonth(d.getMonth()+delta);state.calendarMonth=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`;drawCalendar()}
function openCalendarEvent(key){const [shipmentId,milestoneId]=key.split('|'),plan=calendarPlan(),shipment=shipmentRows(plan).find(s=>s.id===shipmentId),m=shipment?.milestones?.find(x=>x.id===milestoneId);if(!m)return;const start=milestoneDate(m).replaceAll('-',''),end=new Date(milestoneDate(m)+'T00:00:00');end.setDate(end.getDate()+1);const endText=`${end.getFullYear()}${String(end.getMonth()+1).padStart(2,'0')}${String(end.getDate()).padStart(2,'0')}`,title=`${shipment.country_name}: ${m.label||pretty(m.type)}`,details=`Cleared for Takeoff · ${scenarioName(plan)} · ${shipment.route_name||''}`;const google=`https://calendar.google.com/calendar/render?action=TEMPLATE&text=${encodeURIComponent(title)}&dates=${start}/${endText}&details=${encodeURIComponent(details)}`,outlook=`https://outlook.live.com/calendar/0/deeplink/compose?subject=${encodeURIComponent(title)}&startdt=${encodeURIComponent(milestoneDate(m))}&enddt=${encodeURIComponent(end.toISOString().slice(0,10))}&body=${encodeURIComponent(details)}`;showModal(`<div class="modal-head"><div><h2>${esc(title)}</h2><p>${date(milestoneDate(m))} · ${m.duration_days??0} business days</p></div><button class="close-button" data-close aria-label="Close">×</button></div><div class="callout">${esc(details)}</div><div class="modal-actions"><button class="button" data-close>Close</button><a class="button" target="_blank" rel="noreferrer" href="${esc(google)}">Google Calendar ↗</a><a class="button primary" target="_blank" rel="noreferrer" href="${esc(outlook)}">Outlook ↗</a></div>`)}

function drawCountryProgress(shipmentId){const panel=$('#timeline-panel');if(!panel)return;const plan=state.boot.approved_scenario;let shipment=shipmentRows(plan).find(s=>s.id===shipmentId)||shipmentRows(plan).find(s=>s.country_code===state.reqCountry);if(!shipment){panel.innerHTML='<div class="empty">No shipment milestones are available for this country.</div>';return}const milestones=shipment.milestones||[],asOf=plan.as_of,currentIndex=Math.max(0,milestones.findIndex(m=>milestoneDate(m)>=asOf));const impacted=new Set((plan.impacts||[]).filter(i=>i.shipment_id===shipment.id).flatMap(i=>i.milestone_ids||[]));const total=Math.max(1,milestones.length-1),pct=Math.round(currentIndex/total*100);const exposure=shipment.risk_band==='blocked'?'High':shipment.risk_band==='at_risk'||shipment.slack_days<=3?'Watch':'Normal';panel.innerHTML=`<div class="progress-summary"><div><span class="eyebrow">${esc(shipment.country_name)}</span><h3>${esc(shipment.route_name||'Delivery workflow')}</h3><p>Planning date ${date(asOf)} · projected delivery ${date(shipment.projected_delivery)} · ${shipment.slack_days} business days slack</p></div>${badge(shipment.risk_band)}</div><div class="delivery-progress"><i style="width:${pct}%"></i></div><div class="progress-labels"><span>${pct}% through planned stages</span><span>Delay exposure: <b class="exposure-${exposure.toLowerCase()}">${exposure}</b></span></div><div class="stage-track">${milestones.map((m,i)=>{const when=milestoneDate(m),status=i<currentIndex?'complete':i===currentIndex?'current':'upcoming',risk=impacted.has(m.id)||((shipment.risk_band==='blocked'||shipment.risk_band==='at_risk')&&i>=currentIndex);return `<div class="stage ${status} ${risk?'exposed':''}"><div class="stage-marker">${status==='complete'?'✓':i+1}</div><div class="stage-body"><div><b>${esc(m.label||pretty(m.type))}</b>${risk?'<span class="delay-flag">Delay exposure</span>':''}</div><p>${date(when)} · ${m.duration_days??0} business days</p>${risk?`<small>${esc((shipment.reasons||[]).map(r=>typeof r==='string'?r:r.explanation||r.message||'').filter(Boolean).join('; ')||'This stage is affected by the current scenario or low shipment slack.')}</small>`:''}</div></div>`}).join('')}</div>`}
drawTimeline=drawCountryProgress;

const renderRequirementsBase=renderRequirements;
renderRequirements=()=>{renderRequirementsBase();const country=countryList().find(c=>(c.iso_code||c.id)===state.reqCountry),shipment=shipmentRows(state.boot.approved_scenario).find(s=>s.country_code===state.reqCountry),headingNode=$('.page-heading');if(headingNode){headingNode.querySelector('h1').textContent=`${country?.name||state.reqCountry} requirements`;headingNode.querySelector('p').textContent=`Rules active as of ${date(state.reqDate)} · evidence, effective dates, and delivery readiness`;headingNode.insertAdjacentHTML('afterend',`<section class="country-context-card ${esc(shipment?.risk_band||'unknown')}"><div class="country-context-title"><span class="country-context-flag">${flagFor(state.reqCountry)}</span><div><span class="eyebrow">Country supply status</span><h2>${esc(country?.name||state.reqCountry)}</h2><p>Rules active as of <strong>${date(state.reqDate)}</strong></p></div></div>${shipment?`<div class="country-context-metrics"><div><span>Readiness</span>${badge(shipment.risk_band)}</div><div><span>Projected delivery</span><b>${date(shipment.projected_delivery)}</b></div><div><span>Target delivery</span><b>${date(shipment.target_delivery)}</b></div><div><span>${shipment.slack_days<0?'Late by':'Delivery slack'}</span><b class="${shipment.slack_days<0?'late-value':''}">${Math.abs(shipment.slack_days)} business ${Math.abs(shipment.slack_days)===1?'day':'days'}</b></div></div>`:'<div class="empty">No shipment is assigned to this country.</div>'}</section>`)}const countrySelect=$('#req-country'),dateInput=$('#req-date');countrySelect.onchange=e=>{state.reqCountry=e.target.value;state.selectedRule=null;renderRequirements()};dateInput.onchange=e=>{state.reqDate=e.target.value;state.selectedRule=null;renderRequirements()}};

// AI research is a candidate-generation step. Human evidence review and plan approval remain separate.
const renderImportsResearchBase=renderImports;
renderImports=()=>{renderImportsResearchBase();const first=$('.split-layout');if(!first)return;first.insertAdjacentHTML('beforebegin',`<section class="card section-card"><div class="card-head"><div><h2>AI research copilot</h2><p>Extract cited atomic requirements from a registered snapshot or pasted source text.</p></div><span class="mini-pill">${esc(state.boot.research_provider||'unconfigured')} · review required</span></div><div class="callout"><strong>Candidate only.</strong> Every quotation is checked against the saved source text. Extracted rules are forced to needs review and must pass the normal import preview and named human evidence review.</div><div class="toolbar"><select class="select" id="ai-research-source"><option value="">Pasted source</option></select><select class="select" id="ai-research-jurisdiction">${countryList().map(c=>`<option value="${esc(c.iso_code||c.id)}">${esc(c.name)} (${esc(c.iso_code||c.id)})</option>`).join('')}</select><input class="input" id="ai-research-title" placeholder="Source title for pasted text"><input class="input" id="ai-research-url" placeholder="https://official.example/page"></div><label class="field-label" for="ai-research-content">Source text (optional when the registered source already has a snapshot)</label><textarea class="textarea" id="ai-research-content" placeholder="Paste the exact source text here…"></textarea><div class="modal-actions"><button class="button primary" id="ai-extract">Extract candidate requirements</button></div><div id="ai-research-result"></div></section><section class="card section-card"><div class="card-head"><div><h2>AI change analyst</h2><p>Compare the latest two snapshots, retain the raw diff and citations, then confirm the normalized event.</p></div><span class="mini-pill">human confirmation gate</span></div><div class="toolbar"><select class="select" id="ai-change-source"><option value="">Choose a registered source</option></select><button class="button primary" id="ai-analyze-change">Analyze latest change</button></div><div id="ai-change-result"></div></section>`);$('#ai-extract').onclick=()=>runAIExtraction();$('#ai-analyze-change').onclick=()=>runAIChangeAnalysis();loadAIResearchSources();const jurisdictionSelect=document.createElement('select');jurisdictionSelect.id='source-jurisdiction';jurisdictionSelect.className='select';jurisdictionSelect.innerHTML='<option value="">Jurisdiction</option>'+countryList().map(c=>`<option value="${esc(c.iso_code||c.id)}">${esc(c.iso_code||c.id)}</option>`).join('');$('#source-adapter')?.after(jurisdictionSelect);if($('#add-source'))$('#add-source').onclick=addSourceWithJurisdiction};

async function loadAIResearchSources(){try{const data=await api('/api/sources');const options=data.sources.map(s=>`<option value="${esc(s.id)}">${esc(s.title)}${s.jurisdiction?` · ${esc(s.jurisdiction)}`:''}</option>`).join('');const research=$('#ai-research-source'),change=$('#ai-change-source');if(research)research.insertAdjacentHTML('beforeend',options);if(change)change.insertAdjacentHTML('beforeend',options)}catch(e){notify(e.message,'error')}}
async function addSourceWithJurisdiction(){const title=$('#source-title').value.trim(),url=$('#source-url').value.trim(),adapter=$('#source-adapter').value,jurisdiction=$('#source-jurisdiction')?.value;try{await api('/api/sources',{method:'POST',body:JSON.stringify({title,url,adapter,jurisdiction})});await loadSourceRegistry();renderImports();notify('Source registered.')}catch(e){notify(e.message,'error')}}
async function runAIExtraction(sourceId){const box=$('#ai-research-result');if(!box)return;const source_id=sourceId||$('#ai-research-source')?.value||'',body={source_id,jurisdiction:$('#ai-research-jurisdiction')?.value,content:$('#ai-research-content')?.value||undefined,source_title:$('#ai-research-title')?.value.trim(),source_url:$('#ai-research-url')?.value.trim()};box.innerHTML='<div class="loading"><span class="spinner"></span>Extracting and checking cited candidates…</div>';try{const result=await api('/api/research/extract',{method:'POST',body:JSON.stringify(body)});state.aiResearch=result;box.innerHTML=`<div class="callout"><strong>${result.candidates.length} candidate requirements</strong> · ${esc(result.document_note||'Review each candidate and its quotation.')}</div>${result.errors?.length?`<div class="callout"><strong>Rejected output</strong><pre style="white-space:pre-wrap">${esc(JSON.stringify(result.errors,null,2))}</pre></div>`:''}${result.candidates.map(r=>`<div class="repair-card"><div><b>${esc(r.requirement_key)}</b><p>${esc(r.jurisdiction)} · ${esc(r.operator)} · ${esc(JSON.stringify(r.value))} · confidence ${esc(r.confidence)}</p><div class="quote">${esc(r.source_excerpt)}</div><p>Ambiguity: ${esc(r.ambiguity_note||'None recorded')}</p></div></div>`).join('')}${result.candidates.length?'<div class="modal-actions"><button class="button primary" id="ai-use-candidates">Load into validated import preview</button></div>':''}`;if($('#ai-use-candidates'))$('#ai-use-candidates').onclick=()=>{const target=$('#rules-json');target.value=JSON.stringify(result.candidates,null,2);previewRules();target.scrollIntoView({behavior:'smooth',block:'center'})}}catch(e){box.innerHTML=`<div class="empty"><b>Extraction unavailable</b>${esc(e.message)}</div>`}}
async function runAIChangeAnalysis(sourceId){const box=$('#ai-change-result');if(!box)return;const id=sourceId||$('#ai-change-source')?.value;if(!id){notify('Choose a registered source.','warning');return}box.innerHTML='<div class="loading"><span class="spinner"></span>Comparing semantic meaning and checking citations…</div>';try{const result=await api(`/api/sources/${encodeURIComponent(id)}/analyze-change`,{method:'POST',body:'{}'});state.aiChange=result;box.innerHTML=`<div class="callout"><strong>${esc(pretty(result.materiality))}</strong><br>${esc(result.summary)}<br><small>${esc(result.ambiguity_note||'No ambiguity note')}</small></div><div class="split-layout">${result.citations.map(c=>`<div class="quote"><b>${esc(c.label)}</b><br>${esc(c.excerpt)}</div>`).join('')}</div><details><summary>Raw source diff</summary><pre style="white-space:pre-wrap;font-size:10px">${esc(result.raw_diff.join('\n'))}</pre></details><label class="field-label" for="ai-change-event">Normalized proposed event</label><textarea class="textarea" id="ai-change-event">${esc(JSON.stringify(result.event,null,2))}</textarea><div class="toolbar"><input class="input" id="ai-change-reviewer" placeholder="Reviewer name"><input class="input" id="ai-change-note" placeholder="Confirmation note"><button class="button primary" id="ai-confirm-change">Confirm normalized event</button></div>`;$('#ai-confirm-change').onclick=confirmAIChange}catch(e){box.innerHTML=`<div class="empty"><b>Change analysis unavailable</b>${esc(e.message)}</div>`}}
async function confirmAIChange(){const result=state.aiChange,reviewer=$('#ai-change-reviewer')?.value.trim(),note=$('#ai-change-note')?.value.trim();if(!reviewer||!note){notify('Enter a reviewer name and confirmation note.','warning');return}try{const edited=JSON.parse($('#ai-change-event').value),event={title:edited.title,description:edited.description,effective_from:edited.effective_from,changes:edited.changes};await api(`/api/change-analyses/${encodeURIComponent(result.analysis_id)}/confirm`,{method:'POST',body:JSON.stringify({reviewer,note,event})});notify('Change confirmed. The event is now available for deterministic scenario analysis.');await load();nav('scenarios')}catch(e){notify(e.message,'error')}}
